      "<b>树→二叉树</b>：保留每结点到第一个孩子的连线（作左分支）；相邻兄弟间加连线（作右分支）；删去结点到其余孩子的连线；旋转整理。",
      "<b>森林→二叉树</b>：各树分别转二叉树；把各树根视为兄弟，从第一棵根起用右链依次相连。",
      "<b>二叉树→树/森林</b>：左孩子的右链上所有结点改为该结点的孩子；根右链每断开一个结点就是森林新增一棵树的根。",
