   "talk": "民大图论29题次，是大题主战场。2023年二-3把邻接矩阵压缩、Dijkstra、最小生成树三合一考10分，2025又考邻接矩阵加Dijkstra全过程，2024考五地点选商店的最短路径。复习抓两条主线：一是存储与遍历，矩阵求度、邻接表画DFS/BFS序列反复出现，序列随邻接点次序变化，答题先标规则；二是手算算法，Dijkstra用dist表格写松弛，MST写清Prim/Kruskal选边，Floyd迭代、拓扑判环、关键路径ve/vl也要会算。考场先复原图，再逐轮列表写满中间值。",
   "must": [
    "度公式：无向图全部顶点度之和=2e；有向图入度之和=出度之和=e，TD=ID+OD",
    "无向完全图 n(n-1)/2 条边；连通图最少 n-1 条边；强连通有向图最少 n 条弧",
    "DFS类似先序（先根）遍历，BFS类似层序遍历；邻接表 O(n+e)，邻接矩阵 O(n²)",
    "Prim从一个点扩树，O(n²)，适合稠密图；Kruskal按边权选边且不成环，O(eloge)，适合稀疏图",
    "Dijkstra只处理非负权单源问题，每轮选dist最小者入S再松弛",
    "Floyd递推 D^(k)[i][j]=min(D^(k-1)[i][j]，D^(k-1)[i][k]+D^(k-1)[k][j])，O(n³)",
    "Kahn算法反复输出零入度顶点并删弧；输出顶点数小于n说明有环",
    "关键活动判据 l-e=0；ve沿拓扑序取max，vl沿逆拓扑序取min"
   ]
