      "查找 40 的比较路径：22 → 53 → 36 → 40，共比较 4 次",
      "成功 ASL：各层结点数为 1、2、3、3，ASL = (1×1+2×2+3×3+4×3)/9 = (1+4+9+12)/9 = 26/9",
