     "p": "定义：平衡二叉树是空树，或是满足下列条件的二叉排序树——左右子树都是平衡二叉树，且左子树与右子树的高度之差（<b>平衡因子 BF</b> = 左子树高度 - 右子树高度）的绝对值不超过 1。平衡二叉树上任一结点的平衡因子只取 -1、0、1。\n调整方法：插入新结点后，从插入点沿路径向上找到第一个平衡因子绝对值变为 2 的结点 A（最低层不平衡结点），按下面四种失衡形态在 A 处做旋转；旋转后以 A 为根的子树高度恢复到插入前，其上方祖先不再需要调整。"
