     "k": "text",
     "h": "8.7 B 树与 B+ 树",
     "p": "<b>m 阶 B 树</b>的定义性质：① 树中每个结点至多有 m 棵子树，即至多含 m-1 个关键字；② 根结点若非叶子结点则至少有 2 棵子树，除根之外的所有非叶子结点至少有 ⌈m/2⌉ 棵子树，即至少含 ⌈m/2⌉-1 个关键字；③ 结点内关键字按递增次序排列，k 个关键字把记录区间划分为 k+1 段，对应 k+1 棵子树；④ 所有叶子结点（查找失败结点）处在同一层，树高平衡。\n查找过程：先在结点内顺序或折半比较以确定关键字区间，沿对应子树指针向下，直到在某结点命中，或走到叶子层判定失败。"
