   "talk": "查找22题次，ASL是绝对核心，几乎每年都在算比较次数。三类题练熟：折半查找考前提、mid路径和判定树，成功分母n、失败分母n+1要分清；BST按序列构建、写比较路径、算两种ASL再删除，2023二-4这10分原题要会默写，删53用后继36顶替；2025又把BST与AVL构建连考，四种旋转记BF符号组合，++右旋、--左旋、+-先左后右、-+先右后左。散列表两度大题考线性探测与拉链对比，失败分母是地址数11。第K大用快排Partition，平均O(n)，放在排序章讲。",
