   "answer": "int IsHuiwen(char *t){ //判断t字符向量是否为回文，若是，返回1，否则返回0 SeqStack s; int i,len; char temp; InitStack(&s); len=strlen(t); for(i=0;i<len/2;i++) Push(&s,t[i]); //将一半字符入栈 while(!EmptyStack(&s)){ temp=Pop(&s); if(temp!=t[i]) return 0; else i++; } return 1; }",
   "analysis": "将字符串前一半入栈，然后，栈中元素和字符串后一半进行比较。即将第一个出栈元素和后一半串中第一个字符比较，若相等，则再出栈一个元素与后一个字符比较，……，直至栈空，结论为字符序列是回文。在出栈元素与串中字符比较不等时，结论字符序列不是回文。算法中另有定义：#define StackSize 100；typedef char DataType；typedef struct{DataType data[StackSize]; int top;} SeqStack。",
