   "stem": "设哈希表的地址范围为0～17，哈希函数为：H(key)=key%16。用线性探测法处理冲突，输入关键字序列：(10，24，32，17，31，30，46，47，40，63，49)，构造哈希表，试回答下列问题：①画出哈希表的示意图；②若查找关键字63，需要依次与哪些关键字进行比较？③若查找关键字60，需要依次与哪些关键字比较？④假定每个关键字的查找概率相等，求查找成功时的平均查找长度。",
   "options": null,
   "answer": "①哈希表示意（地址0～17）：0:32，1:17，2:63，3:49，4～8空，9:24，10:10，11～13空，14:30，15:31，16:46，17:47。②查找63依次与31、46、47、32、17、63比较。③查找60只与12号空单元比较一次。④ASL=23/11。",
   "analysis": "②查找63，首先要与H(63)=63%16=15号单元内容比较，即63与31比较，不匹配；然后顺移，与46，47，32，17，63相比，一共比较了6次！③查找60，首先要与H(60)=60%16=12号单元内容比较，但因为12号单元为空（应当有空标记），所以应当只比较这一次即可。④对于黑色数据元素，各比较1次，共6次；对红色元素则各不相同，要统计移位的位数。“63”需要6次，“49”需要3次，“40”需要2次，“46”需要3次，“47”需要3次，所以ASL=1/11（6+2+3×3+6）=23/11。",
   "recall": false,
   "note": null,
   "school": "中央民族大学",
   "other": false
