   "topic": "链表选择排序填空",
   "stem": "下面的函数实现对链表 head 进行选择排序，排序完毕，链表中的结点按结点值从小到大链接。\n#include <stdio.h>\ntypedef struct node{\n    char data;\n    struct node *link;\n}node;\nnode *select(node *head){\n    node *p,*q,*r,*s;\n    p = (node *)malloc(sizeof(node));\n    p->link = head;\n    head = p;\n    while(p->link!=NULL){\n        q = p->link;\n        r = p;\n        while((7)______){\n            if(q->link->data < r->link->data)\n                r = q;\n            q = q->link;\n        }\n        if((8)______){\n            s = r->link;\n            r->link = s->link;\n            s->link = (9)______\n            (10)______\n        }\n        p = p->link;\n    }\n    p=head;\n    head = head->link;\n    free(p);\n    return (head);\n}",
   "options": null,
   "answer": "(7) q->link!=NULL (8) r!=p (9) p->link (10) p->link=s",
