   "topic": "用链式存储方法构建二叉树。",
   "stem": "用链式存储方法构建二叉树。",
   "options": [],
   "answer": "/*按先序序列，用递归算法创建二叉链表*/\nBiTree CreatBiTree_Pre(BiTree &BT)\n{\n    char ch;\n    scanf(\"%c\",&ch);\n    if(ch=='0')\n        BT=NULL;//如果是空格字符，则表示为空树。\n    else\n    {\n        BT=(BiTNode *)malloc(sizeof(BiTNode));\n        BT->data=ch;//生成根结点\n        CreatBiTree_Pre(BT->lchild);//递归建立左子树\n        CreatBiTree_Pre(BT->rchild);//递归建立右子树\n    }\n    return 0;\n}",
