   "options": [],
   "answer": "#include <stdio.h>\nint G[105][105] = {0};\nint n;\nint ans = 0;\nint sum;\nvoid dfs(int x)\n{\n    int i;\n    for(i = 1; i <= n; i++)\n    {\n        if(G[x][i] > 0)\n        {\n            sum += G[x][i];\n            dfs(i);\n            sum -= G[x][i];\n        }\n    }\n    if(sum > ans) ans = sum;\n}\nint main()\n{\n    scanf(\"%d\", &n);\n    int i, j;\n    for(i = 1; i <= n; i++)\n        for(j = 1; j <= n; j++)\n            scanf(\"%d\", &G[i][j]);\n    for(i = 1; i <= n; i++)\n    {\n        sum = 0;\n        dfs(i);\n    }\n    printf(\"%d\\n\", ans);\n    return 0;\n}\n时间复杂度为O(n^3)",
