   "stem": "编程实现双向冒泡排序，奇数趟从前往后比较相邻的两个数，将大的数放到后面，偶数趟从后往前比较相邻两个数，将小的数放到前面。",
   "options": [],
   "answer": "#include <stdio.h>\nint arr[105];\nint main()\n{\n    int n; scanf(\"%d\", &n);\n    int i, j;\n    for(i = 1; i <= n; i++)\n        scanf(\"%d\", &arr[i]);\n    int head = 1, tail = n;\n    for(i = 1; i <= n; i++)\n    {\n        if(i % 2 == 1)\n        {\n            head = head + 1;\n            if(head == tail) break;\n            for(j = head; j <= n; j++)\n            {\n                if(arr[j - 1] > arr[j])\n                {\n                    int temp = arr[j];\n                    arr[j] = arr[j - 1];\n                    arr[j - 1] = temp;\n                }\n            }\n        }\n        else{\n            tail = tail - 1;\n            if(head == tail) break;\n            for(j = tail; j >= 1; j--)\n            {\n                if(arr[j + 1] < arr[j])\n                {\n                    int temp = arr[j];\n                    arr[j] = arr[j + 1];\n                    arr[j + 1] = temp;\n                }\n            }\n        }\n    }\n    for(i = 1; i <= n; i++)\n        printf(\"%d \", arr[i]);\n    printf(\"\\n\");\n    return 0;\n}",
