   "title": "顺序有序表插入元素（含空间不足时扩容）",
   "chapter": "线性表",
   "body": "ElemType *newbase = new ElemType[L.listsize + LISTINCREMENT];\nfor (int j = 0; j < L.length; ++j)        //复制数据到新分配的存储空间\n    newbase[j] = L.elem[j];\ndelete[](L.elem);                         //释放旧存储空间\nL.elem = newbase;                         //新基质\nL.listsize += LISTINCREMENT;              //增加存储容量\n\nwhile (e > L.elem[i] && i <= L.length - 1) //寻找第一个大于等于 e 的元素的位置\n    i++;\nfor (int j = L.length - 1; j >= i; j--)    //将所有大于等于 e 的元素后移一个位置\n    L.elem[j + 1] = L.elem[j];\nL.elem[i] = e;   //将 e 放入位置（原先第一个大于等于 e 元素后移一个位置）\n++L.length;      //表长加 1\nreturn OK;",
